import openpyxl
wb=openpyxl.load_workbook("documents/hwk-invoice-may-2025.xlsx")
for ws in wb:
  print(ws.title, ws.dimensions, ws.sheet_state)
  for row in ws.iter_rows():
    for c in row:
      if c.comment: print("COMMENT",c.coordinate,c.comment.text)
      if isinstance(c.value,str) and c.value.startswith("="): print("F",c.coordinate,c.value)
  print([ (k,v.hidden) for k,v in ws.column_dimensions.items() if v.hidden], [k for k,v in ws.row_dimensions.items() if v.hidden])
ws=wb["Disbursements"]
s=0
for r in ws.iter_rows(min_row=2,values_only=True):
  if isinstance(r[0],(int,float)):
    s+=r[6]
    if abs(r[4]*r[5]-r[6])>0.001: print("MISMATCH",r)
print("disb sum",round(s,2))
ws=wb["Professional Fees"]; s=0
for r in ws.iter_rows(min_row=2,values_only=True):
  if isinstance(r[0],(int,float)):
    s+=r[8]
    if abs(r[6]*r[7]-r[8])>0.001: print("MISMATCH",r)
print("fees sum",round(s,2))
